using CrochetCraft.Data;using CrochetCraft.Models;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace CrochetCraft.Controllers;
public class DesignController(AppDbContext db):Controller {
 public async Task<IActionResult> Create(int id){var p=await db.Products.FindAsync(id);if(p==null||!p.Active)return NotFound();ViewBag.Product=p;return View(new DesignVm{ProductId=id});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(DesignVm vm){var uid=HttpContext.Session.GetInt32("UserId");if(uid==null)return RedirectToAction("Login","Account");var p=await db.Products.FindAsync(vm.ProductId);if(p==null||!p.Active)return NotFound();if(!new[]{"Rose","Lavender","Cream","Sage","Sky"}.Contains(vm.Color)||!new[]{"Small","Medium","Large"}.Contains(vm.Size)||!new[]{"Classic","Heart","Flower","Star"}.Contains(vm.Pattern))ModelState.AddModelError("","Invalid design option");if(!ModelState.IsValid){ViewBag.Product=p;return View(vm);}var d=new Design{UserId=uid.Value,ProductId=p.Id,Color=vm.Color,Size=vm.Size,Pattern=vm.Pattern,PersonalName=vm.PersonalName?.Trim()??"",Bow=vm.Bow,GiftWrap=vm.GiftWrap,Quantity=vm.Quantity,UnitPrice=Pricing.UnitPrice(p,vm),YarnRequiredGrams=Math.Round(p.YarnGrams*Pricing.SizeFactor(vm.Size)*vm.Quantity,2)};db.Designs.Add(d);await db.SaveChangesAsync();return RedirectToAction("Checkout","Orders",new{id=d.Id});}
 public async Task<IActionResult> Mine(){var uid=HttpContext.Session.GetInt32("UserId");if(uid==null)return RedirectToAction("Login","Account");return View(await db.Designs.Include(x=>x.Product).Where(x=>x.UserId==uid).OrderByDescending(x=>x.Id).ToListAsync());}
}